options.onRender:
function hgFmtBytes(b,d){if(b===null||b===undefined||isNaN(b))return '--';var u=['B','KB','MB','GB','TB','PB'];var i=0;var v=Math.abs(b);while(v>=1024&&i<u.length-1){v/=1024;i++;}var s=(b<0?'-':'')+v.toFixed(d===undefined||d===null?1:d)+' '+u[i];return s;}
function hgFmtDuration(s){if(s===null||s===undefined||isNaN(s))return '--';var d=Math.floor(s/86400);var h=Math.floor((s%86400)/3600);var m=Math.floor((s%3600)/60);if(d>0)return d+'d '+h+'h';if(h>0)return h+'h '+m+'m';if(m>0)return m+'m';return Math.floor(s)+'s';}
function hgFmt(unit,decimals,v){if(v===null||v===undefined||isNaN(v))return '--';var d=(decimals===null||decimals===undefined)?1:decimals;switch(unit){case 'percent':return v.toFixed(d)+'%';case 'percentunit':return (v*100).toFixed(d)+'%';case 'bytes':return hgFmtBytes(v,d);case 'Bps':return hgFmtBytes(v,d)+'/s';case 'pps':return v.toFixed(d)+' pps';case 's':return hgFmtDuration(v);default:return v.toFixed(d);}}
function hgColor(name){var m={green:'#73bf69','semi-dark-green':'#56A64B','dark-green':'#37872D',yellow:'#ff9830',orange:'#ff9830','dark-orange':'#ff780a',red:'#f2495c','dark-red':'#c4162a',blue:'#5794f2','dark-blue':'#1f60c4',purple:'#b877d9','dark-purple':'#8f3bb8'};return m[name]||name||'#d8d9da';}
function hgThresholdColor(v,steps){if(!steps||!steps.length)return '#d8d9da';if(v===null||v===undefined||isNaN(v))return hgColor(steps[0].color);var c=steps[0].color;for(var i=1;i<steps.length;i++){if(steps[i].value!==null&&steps[i].value!==undefined&&v>=steps[i].value)c=steps[i].color;else break;}return hgColor(c);}
function hgSeries(refId){var all=(htmlGraphics.data&&htmlGraphics.data.series)||[];return all.filter(function(s){return s.refId===refId;});}
function hgFieldValues(f){if(!f||!f.values)return [];return f.values.toArray?f.values.toArray():f.values;}
function hgLastValue(refId){var arr=hgSeries(refId);if(!arr.length)return null;var s=arr[0];if(!s.fields)return null;var f=s.fields.find(function(fld){return fld.type==='number';});if(!f)return null;var vals=hgFieldValues(f);return vals.length?vals[vals.length-1]:null;}
function hgSeriesName(frame){if(frame.name)return frame.name;var f=(frame.fields||[]).find(function(x){return x.type==='number';});if(f&&f.labels){var keys=Object.keys(f.labels);if(keys.length)return keys.map(function(k){return f.labels[k];}).join(' ');}return frame.refId||'';}
var HG_PALETTE=['#73bf69','#5794f2','#ff9830','#f2495c','#b877d9','#8ab8ff','#fade2a','#a352cc','#37872d','#e02f44','#1f60c4','#ff780a'];

function hgRenderStat(rootId,cfg){
  try{
    var root=htmlNode.getElementById(rootId);
    if(!root)return;
    var v=hgLastValue('A');
    var txt=(v===null||v===undefined||isNaN(v))&&cfg.noValue?cfg.noValue:hgFmt(cfg.unit,cfg.decimals,v);
    var color=hgThresholdColor(v,cfg.steps);
    var valEl=root.querySelector('.hg-stat-value');
    valEl.textContent=txt;
    if(cfg.colorMode==='background'){root.style.background=color;root.style.color='#111';valEl.style.color='#111';}
    else{valEl.style.color=color;root.style.background='';}
  }catch(e){}
}

function hgRenderBarGauge(rootId,cfg){
  try{
    var root=htmlNode.getElementById(rootId);
    if(!root)return;
    var frames=hgSeries('A');
    var rows=frames.map(function(f){
      var name=hgSeriesName(f);
      var fld=(f.fields||[]).find(function(x){return x.type==='number';});
      var vals=hgFieldValues(fld);
      var v=vals.length?vals[vals.length-1]:null;
      return {name:name,v:v};
    }).sort(function(a,b){return (b.v||0)-(a.v||0);});
    if(!rows.length){root.innerHTML='<div class="hg-empty">sem dados</div>';return;}
    var min=cfg.min===undefined||cfg.min===null?0:cfg.min;
    var max=cfg.max===undefined||cfg.max===null?100:cfg.max;
    var html=rows.map(function(r){
      var pct=r.v===null||r.v===undefined||isNaN(r.v)?0:Math.max(0,Math.min(100,((r.v-min)/(max-min))*100));
      var color=hgThresholdColor(r.v,cfg.steps);
      var txt=hgFmt(cfg.unit,cfg.decimals,r.v);
      return '<div class="hg-bg-row"><div class="hg-bg-label" title="'+r.name+'">'+r.name+'</div><div class="hg-bg-track"><div class="hg-bg-fill" style="width:'+pct+'%;background:'+color+'"></div></div><div class="hg-bg-value">'+txt+'</div></div>';
    }).join('');
    root.innerHTML=html;
  }catch(e){}
}

function hgRenderTable(rootId,cfg){
  try{
    var root=htmlNode.getElementById(rootId);
    if(!root)return;
    var frames=hgSeries('A');
    if(!frames.length){root.innerHTML='<div class="hg-empty">sem dados</div>';return;}
    var colNames=[];
    var rows=[];
    if(frames.length===1&&(frames[0].fields||[]).length>2){
      var frame=frames[0];
      var fields=frame.fields||[];
      var valueField=fields.find(function(f){return f.type==='number';});
      var labelFields=fields.filter(function(f){return f!==valueField&&f.type!=='time';});
      if(!valueField){root.innerHTML='<div class="hg-empty">sem dados</div>';return;}
      var values=hgFieldValues(valueField);
      if(!values.length){root.innerHTML='<div class="hg-empty">sem dados</div>';return;}
      colNames=labelFields.map(function(f){return f.name;});
      var labelValues=labelFields.map(function(f){return hgFieldValues(f);});
      for(var i=0;i<values.length;i++){
        rows.push({v:values[i],cols:labelFields.map(function(f,li){return labelValues[li][i];})});
      }
    }else{
      var keySet=[];
      frames.forEach(function(f){
        var vf=(f.fields||[]).find(function(x){return x.type==='number';});
        if(vf&&vf.labels){Object.keys(vf.labels).forEach(function(k){if(keySet.indexOf(k)===-1&&k!=='__name__')keySet.push(k);});}
      });
      colNames=keySet;
      frames.forEach(function(f){
        var vf=(f.fields||[]).find(function(x){return x.type==='number';});
        if(!vf)return;
        var vals=hgFieldValues(vf);
        var v=vals.length?vals[vals.length-1]:null;
        var labels=vf.labels||{};
        var cols=keySet.map(function(k){return labels[k]!==undefined?labels[k]:'';});
        if(!keySet.length)cols=[hgSeriesName(f)];
        rows.push({v:v,cols:cols});
      });
      if(!keySet.length)colNames=['série'];
    }
    if(!rows.length){root.innerHTML='<div class="hg-empty">sem dados</div>';return;}
    rows.sort(function(a,b){return (b.v||0)-(a.v||0);});
    var thead='<tr>'+colNames.map(function(n){return '<th>'+n+'</th>';}).join('')+'<th class="hg-num">'+(cfg.valueLabel||'Valor')+'</th></tr>';
    var tbody=rows.map(function(r){
      return '<tr>'+r.cols.map(function(cv){return '<td title="'+cv+'">'+cv+'</td>';}).join('')+'<td class="hg-num">'+hgFmt(cfg.unit,cfg.decimals,r.v)+'</td></tr>';
    }).join('');
    root.innerHTML='<table class="hg-table"><thead>'+thead+'</thead><tbody>'+tbody+'</tbody></table>';
  }catch(e){}
}

function hgRenderChart(rootId,cfg){
  try{
    var root=htmlNode.getElementById(rootId);
    if(!root)return;
    var svgWrap=root.querySelector('.hg-chart-svgwrap');
    var legendWrap=root.querySelector('.hg-chart-legend');
    var frames=[];
    cfg.refIds.forEach(function(rid){hgSeries(rid).forEach(function(f){frames.push(f);});});
    var series=frames.map(function(f){
      var tField=(f.fields||[]).find(function(x){return x.type==='time';});
      var vField=(f.fields||[]).find(function(x){return x.type==='number';});
      if(!tField||!vField)return null;
      return {name:hgSeriesName(f),t:hgFieldValues(tField),v:hgFieldValues(vField)};
    }).filter(function(s){return s&&s.t.length>0;});
    if(!series.length){svgWrap.innerHTML='<div class="hg-empty">sem dados</div>';legendWrap.innerHTML='';return;}
    var rect=svgWrap.getBoundingClientRect();
    var W=Math.max(rect.width,80),H=Math.max(rect.height,50);
    var padL=cfg.leftPad||44,padR=10,padT=8,padB=16;
    var plotW=Math.max(W-padL-padR,10),plotH=Math.max(H-padT-padB,10);
    var yMin=cfg.min!==undefined&&cfg.min!==null?cfg.min:Infinity;
    var yMax=cfg.max!==undefined&&cfg.max!==null?cfg.max:-Infinity;
    var autoMin=cfg.min===undefined||cfg.min===null;
    var autoMax=cfg.max===undefined||cfg.max===null;
    series.forEach(function(s){s.v.forEach(function(val){if(val===null||val===undefined||isNaN(val))return;if(autoMax&&val>yMax)yMax=val;if(autoMin&&val<yMin)yMin=val;});});
    if(!isFinite(yMin))yMin=0;
    if(!isFinite(yMax))yMax=1;
    if(autoMin&&yMin>0)yMin=0;
    if(yMax===yMin)yMax=yMin+1;
    var tMin=Math.min.apply(null,series.map(function(s){return s.t[0];}));
    var tMax=Math.max.apply(null,series.map(function(s){return s.t[s.t.length-1];}));
    if(tMax===tMin)tMax=tMin+1;
    function xOf(t){return padL+((t-tMin)/(tMax-tMin))*plotW;}
    function yOf(v){return padT+plotH-((v-yMin)/(yMax-yMin))*plotH;}
    var svgNS='http://www.w3.org/2000/svg';
    var svg=document.createElementNS(svgNS,'svg');
    svg.setAttribute('width','100%');svg.setAttribute('height','100%');svg.setAttribute('viewBox','0 0 '+W+' '+H);svg.style.display='block';svg.style.overflow='visible';
    function line(x1,y1,x2,y2,stroke,dash){var el=document.createElementNS(svgNS,'line');el.setAttribute('x1',x1);el.setAttribute('y1',y1);el.setAttribute('x2',x2);el.setAttribute('y2',y2);el.setAttribute('stroke',stroke);el.setAttribute('stroke-width','1');if(dash)el.setAttribute('stroke-dasharray',dash);return el;}
    function text(x,y,s,anchor){var el=document.createElementNS(svgNS,'text');el.setAttribute('x',x);el.setAttribute('y',y);el.setAttribute('fill','#8e8e8e');el.setAttribute('font-size','9');if(anchor)el.setAttribute('text-anchor',anchor);el.textContent=s;return el;}
    [0,0.5,1].forEach(function(frac){
      var v=yMin+(yMax-yMin)*(1-frac);
      var y=padT+plotH*frac;
      svg.appendChild(line(padL,y,padL+plotW,y,'rgba(255,255,255,.08)'));
      svg.appendChild(text(padL-6,y+3,hgFmt(cfg.unit,cfg.axisDecimals!==undefined?cfg.axisDecimals:1,v),'end'));
    });
    svg.appendChild(line(padL,padT+plotH,padL+plotW,padT+plotH,'rgba(255,255,255,.15)'));
    var colorFor=function(name,idx){if(cfg.colorOverrides&&cfg.colorOverrides[name])return hgColor(cfg.colorOverrides[name]);return HG_PALETTE[idx%HG_PALETTE.length];};
    series.forEach(function(s,idx){
      var color=colorFor(s.name,idx);
      var pts=[];
      for(var i=0;i<s.t.length;i++){
        if(s.v[i]===null||s.v[i]===undefined||isNaN(s.v[i]))continue;
        pts.push([xOf(s.t[i]),yOf(s.v[i])]);
      }
      if(!pts.length)return;
      if(cfg.area!==false){
        var areaPts=pts.map(function(p){return p[0]+','+p[1];}).join(' ');
        var baseline=yOf(Math.max(yMin,0));
        var areaD='M'+pts[0][0]+','+baseline+' L'+areaPts+' L'+pts[pts.length-1][0]+','+baseline+' Z';
        var areaPath=document.createElementNS(svgNS,'path');
        areaPath.setAttribute('d',areaD);areaPath.setAttribute('fill',color);areaPath.setAttribute('fill-opacity',(cfg.fillOpacity!==undefined?cfg.fillOpacity:12)/100);areaPath.setAttribute('stroke','none');
        svg.appendChild(areaPath);
      }
      var lineD='M'+pts.map(function(p){return p[0]+','+p[1];}).join(' L');
      var linePath=document.createElementNS(svgNS,'path');
      linePath.setAttribute('d',lineD);linePath.setAttribute('fill','none');linePath.setAttribute('stroke',color);linePath.setAttribute('stroke-width','1.5');
      svg.appendChild(linePath);
    });
    var cursorLine=document.createElementNS(svgNS,'line');
    cursorLine.setAttribute('y1',padT);cursorLine.setAttribute('y2',padT+plotH);cursorLine.setAttribute('stroke','rgba(255,255,255,.3)');cursorLine.setAttribute('stroke-width','1');cursorLine.style.display='none';
    svg.appendChild(cursorLine);
    svgWrap.innerHTML='';
    svgWrap.appendChild(svg);
    var tooltip=document.createElement('div');
    tooltip.className='hg-chart-tooltip';
    tooltip.style.display='none';
    svgWrap.appendChild(tooltip);
    svg.addEventListener('mousemove',function(ev){
      var r=svg.getBoundingClientRect();
      var mx=(ev.clientX-r.left)*(W/r.width);
      if(mx<padL||mx>padL+plotW){tooltip.style.display='none';cursorLine.style.display='none';return;}
      var t=tMin+((mx-padL)/plotW)*(tMax-tMin);
      var rows=series.map(function(s){
        var bestI=0,bestD=Infinity;
        for(var i=0;i<s.t.length;i++){var d=Math.abs(s.t[i]-t);if(d<bestD){bestD=d;bestI=i;}}
        return {name:s.name,v:s.v[bestI]};
      });
      cursorLine.setAttribute('x1',mx);cursorLine.setAttribute('x2',mx);cursorLine.style.display='block';
      var html='<div class="hg-tt-time">'+new Date(t).toLocaleString()+'</div>'+rows.map(function(r,i){return '<div class="hg-tt-row"><span class="hg-tt-dot" style="background:'+colorFor(r.name,i)+'"></span><span class="hg-tt-name">'+r.name+'</span><span class="hg-tt-val">'+hgFmt(cfg.unit,cfg.decimals!==undefined?cfg.decimals:2,r.v)+'</span></div>';}).join('');
      tooltip.innerHTML=html;
      tooltip.style.display='block';
      var ttLeft=ev.clientX-r.left+12;
      if(ttLeft+180>r.width)ttLeft=ev.clientX-r.left-192;
      tooltip.style.left=ttLeft+'px';
      tooltip.style.top=(ev.clientY-r.top-10)+'px';
    });
    svg.addEventListener('mouseleave',function(){tooltip.style.display='none';cursorLine.style.display='none';});
    if(legendWrap){
      legendWrap.innerHTML=series.map(function(s,idx){
        var last=null;
        for(var i=s.v.length-1;i>=0;i--){if(s.v[i]!==null&&s.v[i]!==undefined&&!isNaN(s.v[i])){last=s.v[i];break;}}
        return '<span class="hg-legend-item"><span class="hg-legend-dot" style="background:'+colorFor(s.name,idx)+'"></span>'+s.name+' <b>'+hgFmt(cfg.unit,cfg.decimals!==undefined?cfg.decimals:2,last)+'</b></span>';
      }).join('');
    }
  }catch(e){}
}

function hgRenderLogs(rootId,cfg){
  try{
    var root=htmlNode.getElementById(rootId);
    if(!root)return;
    var frames=hgSeries('A');
    if(!frames.length){root.innerHTML='<div class="hg-empty">sem dados</div>';return;}
    var rows=[];
    frames.forEach(function(f){
      var fields=f.fields||[];
      var tField=fields.find(function(x){return x.type==='time';});
      var lineField=fields.find(function(x){return x.type==='string';});
      if(!tField||!lineField)return;
      var tVals=hgFieldValues(tField),lVals=hgFieldValues(lineField);
      var labelsField=fields.find(function(x){return x.name==='labels';});
      var labelVals=labelsField?hgFieldValues(labelsField):null;
      for(var i=0;i<tVals.length;i++){
        var labels=labelVals?labelVals[i]:null;
        var level=labels&&labels.detected_level?labels.detected_level:null;
        var line=lVals[i]||'';
        if(!level){
          var low=String(line).toLowerCase();
          if(low.indexOf('error')>=0||low.indexOf('erro')>=0)level='error';
          else if(low.indexOf('warn')>=0)level='warn';
        }
        rows.push({t:tVals[i],line:line,level:level});
      }
    });
    rows.sort(function(a,b){return b.t-a.t;});
    var LIMIT=500;
    var shown=rows.slice(0,LIMIT);
    var levelColor={error:'#f2495c',critical:'#c4162a',fatal:'#c4162a',warn:'#ff9830',info:'#73bf69',debug:'#5794f2'};
    var html=shown.map(function(r){
      var lc=r.level&&levelColor[r.level]?levelColor[r.level]:'#8e8e8e';
      var tag=r.level?'<span class="hg-log-level" style="background:'+lc+'22;color:'+lc+'">'+r.level+'</span>':'';
      var esc=String(r.line).replace(/&/g,'&amp;').replace(/</g,'&lt;');
      return '<div class="hg-log-row"><span class="hg-log-time">'+new Date(r.t).toLocaleString()+'</span>'+tag+'<span class="hg-log-msg">'+esc+'</span></div>';
    }).join('');
    if(rows.length>LIMIT)html+='<div class="hg-empty">mostrando '+LIMIT+' de '+rows.length+' linhas</div>';
    root.innerHTML=html||'<div class="hg-empty">sem dados</div>';
  }catch(e){}
}

